from functools import lru_cache
import time

# ONE place for settings - change it here, not all over the code
CONFIG = {"transport_percent": 10, "markets": ["Ilaro", "Owode", "Sango"]}

@lru_cache(maxsize=128)               # remember answers we already worked out
def slow_price_lookup(crop, market):
    time.sleep(1)                      # pretend we are asking a slow server
    base = {"tomato": 5000, "yam": 3500, "pepper": 2500}   # practice prices
    return base.get(crop, 0)

def price_with_transport(crop, market):
    price = slow_price_lookup(crop, market)
    return round(price * (1 + CONFIG["transport_percent"] / 100))

start = time.time()
for _ in range(3):                     # the same question, three customers
    print("Tomato at Ilaro: N", price_with_transport("tomato", "Ilaro"))
print("Took", round(time.time() - start, 1), "seconds - not 3!")

import csv, random

# Make a PRACTICE file with 100,000 made-up sales rows
with open("sales.csv", "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["item", "naira"])
    for _ in range(100_000):
        w.writerow([random.choice(["garri", "rice", "beans"]), random.randint(500, 5000)])

def read_sales(path):
    """Generator: hands over ONE row at a time, so memory stays small."""
    with open(path, newline="") as f:
        for row in csv.DictReader(f):
            yield row

totals = {}
for row in read_sales("sales.csv"):
    totals[row["item"]] = totals.get(row["item"], 0) + int(row["naira"])

for item, total in sorted(totals.items()):
    print(f"{item}: N{total:,}")
